@page "/dashboard"
@using sv_2bd7024e573143beb2bc9ef19fe27b82.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p>Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-4 text-danger">@AlertService.LastAlertCount</p>
        <p class="text-muted">Items below minimum level (refreshes every 10s)</p>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling
            await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — immediately refresh alerts for new warehouse
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        StateHasChanged();
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        }
    }

    public async ValueTask DisposeAsync()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        await _cts.CancelAsync();
        _cts.Dispose();
    }
}

